+constexpr auto TypeAryKlassPtrMirror::generate_2d_samples() {
+  std::array<TypeAryKlassPtrMirror, _2d_samples_size> res;
+  size_t sample_idx = 0;
+  for (auto& elem : _2d_elem_samples) {
